def conservar_conversaciones_de_sesion(apps, schema_editor):
    alias = schema_editor.connection.alias
    sesiones = apps.get_model("sessions", "Session").objects.using(alias)
    chats = apps.get_model("dashboard", "ChatAsistente").objects.using(alias)
    turnos = apps.get_model("dashboard", "TurnoAsistente").objects.using(alias)
    usuarios = apps.get_model("cuentas", "Usuario").objects.using(alias)
    proyectos = apps.get_model("dashboard", "Proyecto").objects.using(alias)
    lector = SessionStore()
    for sesion in sesiones.filter(expire_date__gt=timezone.now()).iterator():
        datos = lector.decode(sesion.session_data)
        usuario = str(datos.get("_auth_user_id", ""))
        if not usuario.isascii() or not usuario.isdigit() or len(usuario) > 18:
            continue
        if not usuarios.filter(pk=usuario).exists():
            continue
        for clave, historial in datos.items():
            prefijo, _, proyecto = clave.partition(":")
            if prefijo != "asistente" or not proyecto.isascii() or not proyecto.isdigit() or len(proyecto) > 18:
                continue
            if not isinstance(historial, list) or not proyectos.filter(pk=proyecto).exists():
                continue
            validos = [
                turno for turno in historial if isinstance(turno, dict)
                and all(isinstance(turno.get(campo), str) and turno[campo].strip() for campo in ("pregunta", "respuesta"))
            ]
            if validos:
                chat = chats.create(
                    proyecto_id=proyecto, usuario_id=usuario, version=len(validos),
                    titulo=" ".join(validos[0]["pregunta"].split())[:100],
                )
                turnos.bulk_create([
                    turnos.model(chat=chat, pregunta=turno["pregunta"], respuesta=turno["respuesta"])
                    for turno in validos
                ])


